import React, { useState, useEffect } from 'react';
import './Features.css';

function Features() {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isAutoPlay, setIsAutoPlay] = useState(true);

  const features = [
    {
      icon: '📚',
      title: 'Организация',
      description: 'Создавайте структурированные заметки и базы данных для всего'
    },
    {
      icon: '🎨',
      title: 'Дизайн',
      description: 'Красивый и интуитивный интерфейс для комфортной работы'
    },
    {
      icon: '🔗',
      title: 'Связи',
      description: 'Свяжите идеи вместе и создавайте сложные системы'
    },
    {
      icon: '⚡',
      title: 'Быстрота',
      description: 'Молниеносная работа с любым объемом информации'
    }
  ];

  useEffect(() => {
    if (!isAutoPlay) return;

    const timer = setInterval(() => {
      setCurrentIndex((prevIndex) => (prevIndex + 1) % features.length);
    }, 5000);

    return () => clearInterval(timer);
  }, [isAutoPlay, features.length]);

  const nextSlide = () => {
    setCurrentIndex((prevIndex) => (prevIndex + 1) % features.length);
    setIsAutoPlay(false);
  };

  const prevSlide = () => {
    setCurrentIndex((prevIndex) => (prevIndex - 1 + features.length) % features.length);
    setIsAutoPlay(false);
  };

  const goToSlide = (index) => {
    setCurrentIndex(index);
    setIsAutoPlay(false);
  };

  useEffect(() => {
    if (!isAutoPlay) {
      const timer = setTimeout(() => setIsAutoPlay(true), 8000);
      return () => clearTimeout(timer);
    }
  }, [isAutoPlay]);

  return (
    <section id="features" className="features">
      <div className="features-container">
        <h2>Почему выбирают Kaya?</h2>

        <div className="carousel-wrapper">
          <div className="carousel-container">
            <div 
              className="carousel-track"
              style={{
                transform: `translateX(-${currentIndex * 100}%)`
              }}
            >
              {features.map((feature, index) => (
                <div key={index} className="carousel-slide">
                  <div className="feature-card">
                    <div className="feature-icon">{feature.icon}</div>
                    <h3>{feature.title}</h3>
                    <p>{feature.description}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>

          <button 
            className="carousel-btn prev-btn" 
            onClick={prevSlide}
            aria-label="Previous slide"
          >
            &#10094;
          </button>
          <button 
            className="carousel-btn next-btn" 
            onClick={nextSlide}
            aria-label="Next slide"
          >
            &#10095;
          </button>

          <div className="carousel-dots">
            {features.map((_, index) => (
              <button
                key={index}
                className={`dot ${index === currentIndex ? 'active' : ''}`}
                onClick={() => goToSlide(index)}
                aria-label={`Go to slide ${index + 1}`}
              />
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}

export default Features;
